        const normalized = trimmed
            .replace(/^\.\/agents\//, '')
            .replace(/^\/agents\//, '')
            .replace(/^agents\//, '');
        const filePath = path.join(REPO_ROOT, normalized);
        if (fs.existsSync(filePath)) {
            return fs.readFileSync(filePath, 'utf-8');
        }
        return `<!-- MISSING FILE: ${trimmed} (tried ${normalized}) -->\n`;
    }
    return trimmed;
}

